        }
    }

    override fun serialize(encoder: Encoder, value: StepUpRequest) {
        val output = encoder as? JsonEncoder
            ?: throw SerializationException("StepUpRequest is written as JSON only")
        val element: JsonElement = when (value) {
            is StepUpRequest.Password -> output.json.encodeToJsonElement(StepUpRequestPassword.serializer(), value.value)
            is StepUpRequest.Totp -> output.json.encodeToJsonElement(StepUpRequestTotp.serializer(), value.value)
            is StepUpRequest.BackupCode -> output.json.encodeToJsonElement(StepUpRequestBackupCode.serializer(), value.value)
            is StepUpRequest.EmailCode -> output.json.encodeToJsonElement(StepUpRequestEmailCode.serializer(), value.value)
            is StepUpRequest.Passkey -> output.json.encodeToJsonElement(StepUpRequestPasskey.serializer(), value.value)
            is StepUpRequest.SmsCode -> output.json.encodeToJsonElement(StepUpRequestSmsCode.serializer(), value.value)
